export class CodexChatError extends Error {
	constructor(
		readonly status: 429 | 503,
		message: string,
	) {
		super(message);
		this.name = "CodexChatError";
	}
}

export function codexFailure(message: string) {
	if (/\b429\b|rate.?limit|too many requests/i.test(message)) {
		return new CodexChatError(
			429,
			"Your Codex connection is rate-limited. Please try again later. No media was generated by this chat request.",
		);
	}
	return new CodexChatError(
		503,
		"Codex could not finish this reply. Check your connection and try again. No media was generated by this chat request.",
	);
}
